SELECT commit ->> 'collection' AS event, COUNT(*) AS count FROM {TABLE} GROUP BY event ORDER BY count DESC;
SELECT commit ->> 'collection' AS event, COUNT(*) AS count, COUNT(DISTINCT did) AS users FROM {TABLE} WHERE kind = 'commit' AND commit ->> 'operation' = 'create' GROUP BY event ORDER BY count DESC;
SELECT commit ->> 'collection' AS event, EXTRACT(HOUR FROM CAST(time_us AS TIMESTAMP[us])) AS hour_of_day, COUNT(*) AS count FROM {TABLE} WHERE kind = 'commit' AND commit ->> 'operation' = 'create' AND commit ->> 'collection' IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT did AS user_id, CAST(MIN(time_us) AS TIMESTAMP[us]) AS first_post_ts FROM {TABLE} WHERE kind = 'commit' AND commit ->> 'operation' = 'create' AND commit ->> 'collection' = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3;
SELECT did AS user_id, CAST((MAX(time_us) - MIN(time_us)) / 1000 AS INTEGER) AS activity_span FROM {TABLE} WHERE kind = 'commit' AND commit ->> 'operation' = 'create' AND commit ->> 'collection' = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3;
